const handleMagicLinkSignIn = async () => {
  setError(null);
  setSuccessMessage(null);
  if (!email) {
    setError('Please enter your email to receive a magic link.');
    return;
  }

  setIsLoading(true);
  try {
    const { error: authError } = await supabase.auth.signInWithOtp({
      email,
      options: {
        emailRedirectTo: window.location.origin,
      },
    });

    if (authError) {
      setError(authError.message);
    } else {
      setSuccessMessage('Magic link sent! Check your email to sign in.');
    }
  } catch (err: any) {
    setError(err.message);
  } finally {
    setIsLoading(false);
  }
};

const handleEmailSignIn = async (e: React.FormEvent) => {
  e.preventDefault();
  setError(null);
  setSuccessMessage(null);
  setIsLoading(true);

  try {
    const { error: authError } = await supabase.auth.signInWithPassword({
      email,
      password,
    });

    if (authError) {
      setError(authError.message);
    } else {
      setSuccessMessage('Sign in successful!');
      setEmail('');
      setPassword('');
      // Call onAuthSuccess after a short delay to show the success message
      setTimeout(() => {
        onAuthSuccess();
      }, 1500);
    }
  } catch (err: any) {
    setError(err.message);
  } finally {
    setIsLoading(false);
  }
};

const handleEmailSignUp = async (e: React.FormEvent) => {
  e.preventDefault();
  setError(null);
  setSuccessMessage(null);
  setIsLoading(true);

  try {
    const { error: authError } = await supabase.auth.signUp({
      email,
      password,
    });

    if (authError) {
      setError(authError.message);
    } else {
      setSuccessMessage('Sign up successful! Please check your email to confirm your account.');
      setEmail('');
      setPassword('');
      // Call onAuthSuccess after a short delay to show the success message
      setTimeout(() => {
        onAuthSuccess();
      }, 1500);
    }
  } catch (err: any) {
    setError(err.message);
  } finally {
    setIsLoading(false);
  }
};

